// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../libraries/TransientReentrancyGuard.sol";

interface IERC20Lockable {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

/// @title HanokLiquidityLocker (Cryptographic LP Token Locker & Burner)
/// @notice Secures DEX liquidity with verifiable time-locks (3M, 6M, 1Y, 2Y) and permanent LP burns to protect users from rug-pulls.
contract HanokLiquidityLocker is TransientReentrancyGuard {
    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    struct LockRecord {
        uint256 lockId;
        address lpToken;
        address owner;
        uint256 amount;
        uint256 unlockTimestamp;
        bool isBurntPermanently;
        bool isWithdrawn;
        string projectName;
    }

    uint256 public nextLockId = 1;
    mapping(uint256 => LockRecord) public locks;
    mapping(address => uint256[]) public userLockIds;
    mapping(address => uint256[]) public poolLockIds;

    event LiquidityLocked(
        uint256 indexed lockId,
        address indexed lpToken,
        address indexed owner,
        uint256 amount,
        uint256 unlockTimestamp,
        bool isBurnt,
        string projectName
    );
    event LiquidityWithdrawn(uint256 indexed lockId, address indexed owner, uint256 amount);

    /// @notice Lock LP tokens for a specified duration
    function lockLiquidity(
        address _lpToken,
        uint256 _amount,
        uint256 _unlockTimestamp,
        bool _burnPermanently,
        string memory _projectName
    ) external nonReentrant returns (uint256 lockId) {
        require(_amount > 0, "Zero amount");
        if (!_burnPermanently) {
            require(_unlockTimestamp > block.timestamp + 30 days, "Min lock 30 days");
        }

        lockId = nextLockId++;
        address lockOwner = _burnPermanently ? DEAD_ADDRESS : msg.sender;

        locks[lockId] = LockRecord({
            lockId: lockId,
            lpToken: _lpToken,
            owner: lockOwner,
            amount: _amount,
            unlockTimestamp: _burnPermanently ? type(uint256).max : _unlockTimestamp,
            isBurntPermanently: _burnPermanently,
            isWithdrawn: false,
            projectName: _projectName
        });

        userLockIds[msg.sender].push(lockId);
        poolLockIds[_lpToken].push(lockId);

        address destination = _burnPermanently ? DEAD_ADDRESS : address(this);
        require(IERC20Lockable(_lpToken).transferFrom(msg.sender, destination, _amount), "Transfer failed");

        emit LiquidityLocked(lockId, _lpToken, lockOwner, _amount, locks[lockId].unlockTimestamp, _burnPermanently, _projectName);
    }

    /// @notice Withdraw unlocked LP tokens after maturity
    function withdraw(uint256 _lockId) external nonReentrant {
        LockRecord storage record = locks[_lockId];
        require(!record.isBurntPermanently, "Permanently burnt LP");
        require(!record.isWithdrawn, "Already withdrawn");
        require(msg.sender == record.owner, "Only owner");
        require(block.timestamp >= record.unlockTimestamp, "Lock not matured");

        record.isWithdrawn = true;
        require(IERC20Lockable(record.lpToken).transfer(msg.sender, record.amount), "Transfer failed");

        emit LiquidityWithdrawn(_lockId, msg.sender, record.amount);
    }

    /// @notice Verify lock status for DEX project badges
    function getPoolLockSummary(address _lpToken) external view returns (
        uint256 totalLockedAmount,
        bool hasActiveLock,
        bool hasPermanentBurn,
        uint256 longestUnlockTimestamp
    ) {
        uint256[] memory ids = poolLockIds[_lpToken];
        for (uint256 i = 0; i < ids.length; i++) {
            LockRecord memory rec = locks[ids[i]];
            if (!rec.isWithdrawn) {
                totalLockedAmount += rec.amount;
                hasActiveLock = true;
                if (rec.isBurntPermanently) {
                    hasPermanentBurn = true;
                }
                if (rec.unlockTimestamp > longestUnlockTimestamp && !rec.isBurntPermanently) {
                    longestUnlockTimestamp = rec.unlockTimestamp;
                }
            }
        }
    }
}

contracts/libraries/TransientReentrancyG.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title TransientReentrancyGuard
/// @notice Gas-optimized reentrancy lock utilizing Cancun EVM EIP-1153 transient storage (TSTORE / TLOAD).
/// @dev Reduces gas overhead from ~20,000 gas (SSTORE) to ~100 gas per invocation on Giwa Chain (op-reth).
abstract contract TransientReentrancyGuard {
    // keccak256("giwa.transient.reentrancy.guard")
    bytes32 private constant REENTRANCY_SLOT = 0xb532073b72e1fef2d324f3dd033ea331ee0d9c4cfa5bedba4e00f3d374264997;

    error ReentrancyGuardReentrantCall();

    modifier nonReentrant() {
        _enter();
        _;
        _exit();
    }

    function _enter() internal {
        assembly {
            if tload(REENTRANCY_SLOT) {
                // Revert with ReentrancyGuardReentrantCall() selector: 0x3ee52b14
                mstore(0x00, 0x3ee52b14)
                revert(0x1c, 0x04)
            }
            tstore(REENTRANCY_SLOT, 1)
        }
    }

    function _exit() internal {
        assembly {
            tstore(REENTRANCY_SLOT, 0)
        }
    }
}

contracts/periphery/GiwaUniversalRouter..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../interfaces/IGiwaUniversalRouter.sol";
import "../interfaces/IGiwaPoolFactory.sol";
import "../interfaces/IGiwaCLPool.sol";
import "../interfaces/IGiwaStablePool.sol";
import "../interfaces/IPermit2.sol";
import "../libraries/TransientReentrancyGuard.sol";

interface IWETH9 {
    function deposit() external payable;
    function withdraw(uint256) external;
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address src, address dst, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20PermitTransfer {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address src, address dst, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @title GiwaUniversalRouter
/// @notice Universal Router for Giwa Chain aggregating swaps across Concentrated Liquidity and Stableswap pools with Multi-Hop SOR and Permit2.
contract GiwaUniversalRouter is IGiwaUniversalRouter, TransientReentrancyGuard {
    address public immutable factory;
    address public immutable WETH9;
    address public immutable permit2;

    modifier checkDeadline(uint256 deadline) {
        require(block.timestamp <= deadline, "Router: EXPIRED");
        _;
    }

    constructor(address _factory, address _weth9, address _permit2) {
        require(_factory != address(0) && _weth9 != address(0), "Router: ZERO_ADDRESS");
        factory = _factory;
        WETH9 = _weth9;
        permit2 = _permit2;
    }

    receive() external payable {
        require(msg.sender == WETH9, "Router: NOT_WETH9");
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        override
        nonReentrant
        checkDeadline(params.deadline)
        returns (uint256 amountOut)
    {
        // Handle ETH input wrapping or ERC20 pulling
        if (msg.value > 0) {
            require(params.tokenIn == WETH9, "Router: ETH_TOKEN_MISMATCH");
            require(msg.value == params.amountIn, "Router: INVALID_ETH_VALUE");
            IWETH9(WETH9).deposit{value: msg.value}();
        } else {
            _safeTransferFrom(params.tokenIn, msg.sender, address(this), params.amountIn);
        }

        amountOut = _executeSingleHop(
            params.tokenIn,
            params.tokenOut,
            params.fee,
            params.isStable,
            params.amountIn,
            params.amountOutMinimum,
            params.sqrtPriceLimitX96,
            params.recipient
        );

        emit RouteExecuted(
            msg.sender,
            params.recipient,
            params.tokenIn,
            params.tokenOut,
            params.amountIn,
            amountOut,
            false
        );
    }

    function exactInputSingleWithPermit2(
        ExactInputSingleParams calldata params,
        Permit2Signature calldata permit2Sig
    ) external override nonReentrant checkDeadline(params.deadline) returns (uint256 amountOut) {
        require(permit2 != address(0), "Router: PERMIT2_DISABLED");
        require(permit2Sig.permit.permitted.token == params.tokenIn, "Router: PERMIT_TOKEN_MISMATCH");

        // Pull tokens via Permit2
        IPermit2(permit2).permitTransferFrom(
            permit2Sig.permit,
            IPermit2.SignatureTransferDetails({
                to: address(this),
                requestedAmount: params.amountIn
            }),
            msg.sender,
            permit2Sig.signature
        );

        amountOut = _executeSingleHop(
            params.tokenIn,
            params.tokenOut,
            params.fee,
            params.isStable,
            params.amountIn,
            params.amountOutMinimum,
            params.sqrtPriceLimitX96,
            params.recipient
        );

        emit RouteExecuted(
            msg.sender,
            params.recipient,
            params.tokenIn,
            params.tokenOut,
            params.amountIn,
            amountOut,
            false
        );
    }

    function exactInputMultiHop(ExactInputMultiHopParams calldata params)
        external
        payable
        override
        nonReentrant
        checkDeadline(params.deadline)
        returns (uint256 amountOut)
    {
        require(params.hops.length > 0, "Router: EMPTY_HOPS");

        address initialTokenIn = params.hops[0].tokenIn;

        // Handle ETH input wrapping or ERC20 pulling
        if (msg.value > 0) {
            require(initialTokenIn == WETH9, "Router: ETH_TOKEN_MISMATCH");
            require(msg.value == params.amountIn, "Router: INVALID_ETH_VALUE");
            IWETH9(WETH9).deposit{value: msg.value}();
        } else {
            _safeTransferFrom(initialTokenIn, msg.sender, address(this), params.amountIn);
        }

        amountOut = _executeMultiHop(params.hops, params.amountIn, params.amountOutMinimum, params.recipient);

        emit RouteExecuted(
            msg.sender,
            params.recipient,
            initialTokenIn,
            params.hops[params.hops.length - 1].tokenOut,
            params.amountIn,
            amountOut,
            false
        );
    }

    function exactInputMultiHopWithPermit2(
        ExactInputMultiHopParams calldata params,
        Permit2Signature calldata permit2Sig
    ) external override nonReentrant checkDeadline(params.deadline) returns (uint256 amountOut) {
        require(permit2 != address(0), "Router: PERMIT2_DISABLED");
        require(params.hops.length > 0, "Router: EMPTY_HOPS");

        address initialTokenIn = params.hops[0].tokenIn;

        require(permit2Sig.permit.permitted.token == initialTokenIn, "Router: PERMIT_TOKEN_MISMATCH");
        IPermit2(permit2).permitTransferFrom(
            permit2Sig.permit,
            IPermit2.SignatureTransferDetails({
                to: address(this),
                requestedAmount: params.amountIn
            }),
            msg.sender,
            permit2Sig.signature
        );

        amountOut = _executeMultiHop(params.hops, params.amountIn, params.amountOutMinimum, params.recipient);

        emit RouteExecuted(
            msg.sender,
            params.recipient,
            initialTokenIn,
            params.hops[params.hops.length - 1].tokenOut,
            params.amountIn,
            amountOut,
            false
        );
    }

    function _executeSingleHop(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        bool isStable,
        uint256 amountIn,
        uint256 amountOutMinimum,
        uint160 sqrtPriceLimitX96,
        address recipient
    ) internal returns (uint256 amountOut) {
        require(tokenIn != tokenOut && amountIn > 0 && amountIn <= uint256(type(int256).max), "Router: INVALID_INPUT");
        require(recipient != address(0), "Router: ZERO_RECIPIENT");
        address pool = IGiwaPoolFactory(factory).getPool(tokenIn, tokenOut, fee, isStable);
        require(pool != address(0), "Router: POOL_NOT_FOUND");

        _safeApprove(tokenIn, pool, amountIn);

        if (isStable) {
            uint256 i = IGiwaStablePool(pool).coins(0) == tokenIn ? 0 : 1;
            uint256 j = i == 0 ? 1 : 0;
            amountOut = IGiwaStablePool(pool).exchange(i, j, amountIn, amountOutMinimum);
            _safeTransfer(tokenOut, recipient, amountOut);
        } else {
            bool zeroForOne = tokenIn < tokenOut;
            uint160 sqrtLimit = sqrtPriceLimitX96 == 0
                ? (zeroForOne ? 4295128740 : 1461446703485210103287273052203988822378723970341)
                : sqrtPriceLimitX96;

            (int256 amount0, int256 amount1) = IGiwaCLPool(pool).swap(
                recipient,
                zeroForOne,
                int256(amountIn),
                sqrtLimit,
                ""
            );
            // A price limit can leave unspent input in this router, where public
            // sweep helpers could expose it. Require a full fill atomically.
            require(uint256(zeroForOne ? amount0 : amount1) == amountIn, "Router: PARTIAL_FILL");
            amountOut = zeroForOne ? uint256(-amount1) : uint256(-amount0);
        }

        _safeApprove(tokenIn, pool, 0);
        require(amountOut >= amountOutMinimum, "Router: INSUFFICIENT_OUTPUT_AMOUNT");
    }

    function _executeMultiHop(
        SwapHop[] memory hops,
        uint256 amountIn,
        uint256 amountOutMinimum,
        address recipient
    ) internal returns (uint256 currentAmount) {
        currentAmount = amountIn;
        uint256 len = hops.length;

        for (uint256 i = 0; i < len; i++) {
            SwapHop memory hop = hops[i];
            if (i > 0) require(hops[i - 1].tokenOut == hop.tokenIn, "Router: DISCONNECTED_HOPS");
            address targetRecipient = (i == len - 1) ? recipient : address(this);
            uint256 minOut = (i == len - 1) ? amountOutMinimum : 1;

            currentAmount = _executeSingleHop(
                hop.tokenIn,
                hop.tokenOut,
                hop.fee,
                hop.isStable,
                currentAmount,
                minOut,
                hop.sqrtPriceLimitX96,
                targetRecipient
            );
        }
    }

    function exactInput(ExactInputParams calldata params)
        external
        payable
        override
        nonReentrant
        checkDeadline(params.deadline)
        returns (uint256 amountOut)
    {
        revert("Router: EXACT_INPUT_PATH_UNSUPPORTED");
    }

    function exactOutputSingle(ExactOutputSingleParams calldata params)
        external
        payable
        override
        nonReentrant
        checkDeadline(params.deadline)
        returns (uint256 amountIn)
    {
        revert("Router: EXACT_OUTPUT_UNSUPPORTED");
    }

    function unwrapWETH9(uint256, address) external payable override nonReentrant {
        // Output is delivered directly to the swap recipient. There is no
        // atomic multicall or per-user custody accounting for public sweeps.
        revert("Router: UNWRAP_UNSUPPORTED");
    }

    function sweepToken(address, uint256, address) external payable override nonReentrant {
        revert("Router: SWEEP_UNSUPPORTED");
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20PermitTransfer.transfer.selector, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Router: TRANSFER_FAILED");
    }

    function _safeApprove(address token, address spender, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSignature("approve(address,uint256)", spender, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Router: APPROVE_FAILED");
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20PermitTransfer.transferFrom.selector, from, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Router: TRANSFER_FROM_FAILED");
    }
}

contracts/pool/KRWCStableswapPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../libraries/TransientReentrancyGuard.sol";

interface IERC20FX {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
}

/// @title KRWCStableswapPool (Korean Won Deep FX Curve)
/// @notice Optimized Curve StableSwap invariant (A = 1000) for Korean Won Stablecoin (KRWC) paired with USD/EUR stablecoins.
/// @dev Implements rate scaling (1 USD = 1,400 KRW, 1 EUR = 1,520 KRW) to ensure 1:1 normalized virtual invariant math.
contract KRWCStableswapPool is TransientReentrancyGuard {
    uint256 public constant N_COINS = 4; // 0: KRWC, 1: USDC, 2: EURC, 3: USYC
    uint256 public constant A_PRECISION = 100;
    uint256 public constant FEE_DENOMINATOR = 10**10;

    address[N_COINS] public coins;
    uint256[N_COINS] public balances;
    uint256[N_COINS] public precisionMultipliers; // converts token decimals to 18 decimals
    uint256[N_COINS] public rateScalers;          // FX rate normalized to KRW base (1 KRWC = 1e18, 1 USDC = 1400e18)

    uint256 public A; // Amplification coefficient (A = 1000)
    uint256 public fee; // Base fee (e.g., 4000000 = 0.04%)
    uint256 public adminFee = 5000000000; // 50% of swap fee to feeVault
    address public feeVault;
    address public owner;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    event TokenExchange(
        address indexed buyer,
        uint256 soldId,
        uint256 tokensSold,
        uint256 boughtId,
        uint256 tokensBought
    );
    event AddLiquidity(
        address indexed provider,
        uint256[N_COINS] amounts,
        uint256[N_COINS] fees,
        uint256 invariant,
        uint256 tokenSupply
    );
    event RemoveLiquidity(
        address indexed provider,
        uint256[N_COINS] amounts,
        uint256[N_COINS] fees,
        uint256 tokenSupply
    );
    event RateUpdated(uint256 indexed coinId, uint256 newRate);
    event RampA(uint256 oldA, uint256 newA, uint256 initialTime, uint256 futureTime);

    constructor(
        address _krwc,
        address _usdc,
        address _eurc,
        address _usyc,
        address _feeVault
    ) {
        owner = msg.sender;
        coins[0] = _krwc;
        coins[1] = _usdc;
        coins[2] = _eurc;
        coins[3] = _usyc;
        feeVault = _feeVault;

        A = 1000 * A_PRECISION; // A = 1000 for deep Korean FX curve
        fee = 4000000; // 0.04%

        // Precision multipliers to 18 decimals
        precisionMultipliers[0] = 10**(18 - _getDecimals(_krwc)); // KRWC (6 dec -> 1e12)
        precisionMultipliers[1] = 10**(18 - _getDecimals(_usdc)); // USDC (6 dec -> 1e12)
        precisionMultipliers[2] = 10**(18 - _getDecimals(_eurc)); // EURC (6 dec -> 1e12)
        precisionMultipliers[3] = 10**(18 - _getDecimals(_usyc)); // USYC (6 dec -> 1e12)

        // Initial standard FX rates normalized to KRW base:
        // 1 KRWC = 1.0 (1e18)
        // 1 USDC = 1,400.0 KRW (1400e18)
        // 1 EURC = 1,521.74 KRW (1521740000000000000000)
        // 1 USYC = 1,400.0 KRW (1400e18)
        rateScalers[0] = 1e18;
        rateScalers[1] = 1400 * 1e18;
        rateScalers[2] = 1521740000000000000000;
        rateScalers[3] = 1400 * 1e18;
    }

    function _getDecimals(address token) private view returns (uint8) {
        if (token.code.length == 0) return 6;
        (bool success, bytes memory data) = token.staticcall(abi.encodeWithSignature("decimals()"));
        if (success && data.length >= 32) {
            uint256 dec = abi.decode(data, (uint256));
            return dec <= 18 ? uint8(dec) : 18;
        }
        return 6;
    }

    /// @notice Update currency conversion rate for FX valuation
    function setRateScaler(uint256 coinId, uint256 newRate) external {
        require(msg.sender == owner, "Only owner");
        require(coinId < N_COINS, "Invalid coinId");
        require(newRate > 0, "Rate must be > 0");
        rateScalers[coinId] = newRate;
        emit RateUpdated(coinId, newRate);
    }

    /// @notice Normalized balances converted to 18-decimal KRW purchasing power parity
    function _xp() internal view returns (uint256[N_COINS] memory xp) {
        for (uint256 i = 0; i < N_COINS; i++) {
            // balance * precisionMultiplier * rateScaler / 1e18
            xp[i] = (balances[i] * precisionMultipliers[i] * rateScalers[i]) / 1e18;
        }
    }

    /// @notice Calculate D invariant for N coins
    function _get_D(uint256[N_COINS] memory xp, uint256 amp) internal pure returns (uint256) {
        uint256 S = 0;
        for (uint256 i = 0; i < N_COINS; i++) {
            S += xp[i];
        }
        if (S == 0) return 0;

        uint256 Dprev = 0;
        uint256 D = S;
        uint256 Ann = amp * N_COINS;

        for (uint256 iter = 0; iter < 255; iter++) {
            uint256 D_P = D;
            for (uint256 i = 0; i < N_COINS; i++) {
                D_P = (D_P * D) / (xp[i] * N_COINS);
            }
            Dprev = D;
            D = (Ann * S / A_PRECISION + D_P * N_COINS) * D / (((Ann - A_PRECISION) * D / A_PRECISION) + ((N_COINS + 1) * D_P));
            if (D > Dprev) {
                if (D - Dprev <= 1) return D;
            } else {
                if (Dprev - D <= 1) return D;
            }
        }
        return D;
    }

    /// @notice Calculate token out amount for token in
    function _get_y(uint256 i, uint256 j, uint256 x, uint256[N_COINS] memory xp) internal view returns (uint256) {
        uint256 amp = A;
        uint256 D = _get_D(xp, amp);
        uint256 Ann = amp * N_COINS;
        uint256 c = D;
        uint256 S_ = 0;
        uint256 _x = 0;

        for (uint256 k = 0; k < N_COINS; k++) {
            if (k == i) {
                _x = x;
            } else if (k != j) {
                _x = xp[k];
            } else {
                continue;
            }
            S_ += _x;
            c = (c * D) / (_x * N_COINS);
        }
        c = (c * D * A_PRECISION) / (Ann * N_COINS);
        uint256 b = S_ + (D * A_PRECISION) / Ann;
        uint256 y_prev = 0;
        uint256 y = D;

        for (uint256 iter = 0; iter < 255; iter++) {
            y_prev = y;
            y = (y * y + c) / (2 * y + b - D);
            if (y > y_prev) {
                if (y - y_prev <= 1) return y;
            } else {
                if (y_prev - y <= 1) return y;
            }
        }
        return y;
    }

    /// @notice Estimate output tokens for a swap
    function get_dy(uint256 i, uint256 j, uint256 dx) external view returns (uint256) {
        require(i < N_COINS && j < N_COINS && i != j, "Invalid coin index");
        uint256[N_COINS] memory xp = _xp();

        uint256 dx_normalized = (dx * precisionMultipliers[i] * rateScalers[i]) / 1e18;
        uint256 x = xp[i] + dx_normalized;
        uint256 y = _get_y(i, j, x, xp);

        uint256 dy_normalized = xp[j] - y - 1;
        uint256 _fee = (fee * dy_normalized) / FEE_DENOMINATOR;
        dy_normalized = dy_normalized - _fee;

        // Convert back from normalized KRW base to target token units
        return (dy_normalized * 1e18) / (precisionMultipliers[j] * rateScalers[j]);
    }

    /// @notice Execute exchange between KRWC and other foreign stablecoins
    function exchange(
        uint256 i,
        uint256 j,
        uint256 dx,
        uint256 min_dy,
        address recipient
    ) external nonReentrant returns (uint256) {
        require(i < N_COINS && j < N_COINS && i != j, "Invalid coin index");
        require(dx > 0, "dx must be > 0");

        uint256[N_COINS] memory xp = _xp();
        uint256 dx_normalized = (dx * precisionMultipliers[i] * rateScalers[i]) / 1e18;
        uint256 x = xp[i] + dx_normalized;
        uint256 y = _get_y(i, j, x, xp);

        uint256 dy_normalized = xp[j] - y - 1;
        uint256 dy_fee = (fee * dy_normalized) / FEE_DENOMINATOR;
        uint256 dy_admin_fee = (dy_fee * adminFee) / FEE_DENOMINATOR;

        dy_normalized = dy_normalized - dy_fee;

        uint256 dy = (dy_normalized * 1e18) / (precisionMultipliers[j] * rateScalers[j]);
        require(dy >= min_dy, "Slippage: dy < min_dy");

        // Update balances
        balances[i] += dx;
        balances[j] -= (dy + (dy_admin_fee * 1e18) / (precisionMultipliers[j] * rateScalers[j]));

        // Transfer tokens
        require(IERC20FX(coins[i]).transferFrom(msg.sender, address(this), dx), "TransferIn failed");
        require(IERC20FX(coins[j]).transfer(recipient, dy), "TransferOut failed");

        if (dy_admin_fee > 0 && feeVault != address(0)) {
            uint256 adminAmount = (dy_admin_fee * 1e18) / (precisionMultipliers[j] * rateScalers[j]);
            if (adminAmount > 0) {
                IERC20FX(coins[j]).transfer(feeVault, adminAmount);
            }
        }

        emit TokenExchange(msg.sender, i, dx, j, dy);
        return dy;
    }

    /// @notice Get virtual price of the LP token
    function get_virtual_price() external view returns (uint256) {
        uint256 D = _get_D(_xp(), A);
        if (totalSupply == 0) return 1e18;
        return (D * 1e18) / totalSupply;
    }
}

